\end{equation*}

Proof. Given any two codewords, $\mathbf{c}_{1} \neq \mathbf{c}_{2} \in C$, the following is true (as $C$ has distance ${ }^{15} 3$ ):


\begin{equation*}
B\left(\mathbf{c}_{1}, 1\right) \cap B\left(\mathbf{c}_{2}, 1\right)=\varnothing . \tag{1.12}
\end{equation*}


See Figure 1.4 for an illustration.\\
Note that for all $\mathbf{x} \in\{0,1\}^{n}$ (see Exercise 1.16),


\begin{equation*}
|B(\mathbf{x}, 1)|=n+1 . \tag{1.13}
\end{equation*}


Now consider the union of all Hamming balls centered around some codeword; their union is a subset of $\{0,1\}^{n}$. In other words,


\begin{equation*}
\left|\bigcup_{\mathbf{c} \in C} B(\mathbf{c}, 1)\right| \leq 2^{n} . \tag{1.14}
\end{equation*}


As (1.12) holds for every pair of distinct codewords,


\begin{align*}
\left|\bigcup_{\mathbf{c} \in C} B(\mathbf{c}, 1)\right| & =\sum_{\mathbf{c} \in C}|B(\mathbf{c}, 1)| \\
& =\sum_{\mathbf{c} \in C}(n+1)  \tag{1.15}\\
& =2^{k} \cdot(n+1), \tag{1.16}
\end{align*}


\footnotetext{${ }^{15}$ Assume that $\mathbf{y} \in B\left(\mathbf{c}_{1}, 1\right) \cap B\left(\mathbf{c}_{2}, 1\right)$, that is $\Delta\left(\mathbf{y}, \mathbf{c}_{1}\right) \leq 1$ and $\Delta\left(\mathbf{y}, \mathbf{c}_{2}\right) \leq 1$. Thus, by the triangle inequality $\Delta\left(\mathbf{c}_{1}, \mathbf{c}_{2}\right) \leq$ $2<3$, which is a contradiction.
