\left|C_{\mathbf{x}}\right| \leq \frac{q d}{q d-(q-1) n^{\prime}} \leq q d \leq q n, \tag{4.7}
\end{equation*}


where the second inequality follows from the fact that $q d-(q-1) n^{\prime}$ is a positive integer and the third is immediate from $d \leq n$.

Lemma 4.4.3 (Geometric Lemma). Let $\mathbf{v}_{1}, \mathbf{v}_{2}, \ldots, \mathbf{v}_{m} \in \mathbb{R}^{N}$ be non-zero vectors.

\begin{itemize}
  \item[1.] If $\left\langle\mathbf{v}_{i}, \mathbf{v}_{j}\right\rangle \leq 0$ for all $i \neq j$, then $m \leq 2 N$.
  \item[2.] Let $\mathbf{v}_{i}$ be unit vectors for $1 \leq i \leq m$. Further, if $\left\langle\mathbf{v}_{i}, \mathbf{v}_{j}\right\rangle \leq-\varepsilon<0$ for all $i \neq j$, then $m \leq 1+\frac{1}{\varepsilon}$.
\end{itemize}

Alternate proof of first part. We now present an alternate proof of the first result, which we do by induction on $n$. Note that in the base case of $N=0$, we have $m=0$, which satisfies the claimed inequality $m \leq 2 N$.

In the general case, we have $m \geq 1$ non-zero vectors $\mathbf{v}_{1}, \ldots, \mathbf{v}_{m} \in \mathbb{R}^{N}$ such that for every $i \neq j$,


\begin{equation*}
\left\langle\mathbf{v}_{i}, \mathbf{v}_{j}\right\rangle \leq 0 . \tag{4.8}
\end{equation*}


Since rotating all the vectors by the same amount does not change the sign of the inner product (nor does scaling any of the vectors), w.l.o.g. we can assume that $\mathbf{v}_{m}=\langle 1,0, \ldots, 0\rangle$. For $1 \leq i \leq m-1$, denote the vectors as $\mathbf{v}_{i}=\left\langle\alpha_{i}, \mathbf{y}_{i}\right\rangle$, for some $\alpha_{i} \in \mathbb{R}$ and $\mathbf{y}_{i} \in \mathbb{R}^{N-1}$. Now, for any $i \neq 1,\left\langle\mathbf{v}_{1}, \mathbf{v}_{i}\right\rangle=1 \cdot \alpha_{i}+\sum_{i=2}^{m} 0=\alpha_{i}$. However, we know from (4.8) that $\left\langle\mathbf{v}_{1}, \mathbf{v}_{i}\right\rangle \leq 0$, which in turn implies that


\begin{equation*}
\alpha_{i} \leq 0 . \tag{4.9}
\end{equation*}


Next, we claim that at most one of $\mathbf{y}_{1}, \ldots, \mathbf{y}_{m-1}$ can be the all zeroes vector, $\mathbf{0}$. If not, assume w.l.o.g., that $\mathbf{y}_{1}=\mathbf{y}_{2}=\mathbf{0}$. This in turn implies that

$$
\begin{aligned}
\left\langle\mathbf{v}_{1}, \mathbf{v}_{2}\right\rangle & =\alpha_{1} \cdot \alpha_{2}+\left\langle\mathbf{y}_{1}, \mathbf{y}_{2}\right\rangle \\
& =\alpha_{1} \cdot \alpha_{2}+0 \\
& =\alpha_{1} \cdot \alpha_{2} \\
& >0
\end{aligned}
$$

where the last inequality follows from the subsequent argument. As $\mathbf{v}_{1}=\left\langle\alpha_{1}, \mathbf{0}\right\rangle$ and $\mathbf{v}_{2}=\left\langle\alpha_{2}, \mathbf{0}\right\rangle$ are non-zero, we have that $\alpha_{1}, \alpha_{2} \neq 0$. (4.9) then implies that $\alpha_{1}, \alpha_{2}<0$. However, $\left\langle\mathbf{v}_{1}, \mathbf{v}_{2}\right\rangle>0$ contradicts (4.8).

Thus, w.l.o.g., assume that $\mathbf{y}_{1}, \ldots, \mathbf{y}_{m-2}$ are all non-zero vectors. Further, note that for every $i \neq j \in[m-2],\left\langle\mathbf{y}_{i}, \mathbf{y}_{j}\right\rangle=\left\langle\mathbf{v}_{i}, \mathbf{v}_{j}\right\rangle-\alpha_{i} \cdot \alpha_{j} \leq\left\langle\mathbf{v}_{i}, \mathbf{v}_{j}\right\rangle \leq 0$. Thus, we have reduced problem on $m$ vectors with dimension $N$ to an equivalent problem on $m-2$ vectors with dimension $N-1$. By induction we have $m-2 \leq 2(N-1)$ and thus implying $m \leq 2 N$. \(\square\)

In the general case, we have $m \geq 1$ non-zero vectors $\mathbf{v}_{1}, \ldots, \mathbf{v}_{m} \in \mathbb{R}^{N}$ such that for every $i \neq j$,


\begin{equation*}
\left\langle\mathbf{v}_{i}, \mathbf{v}_{j}\right\rangle \leq 0 . \tag{4.8}
\end{equation*}


Since rotating all the vectors by the same amount does not change the sign of the inner product (nor does scaling any of the vectors), w.l.o.g. we can assume that $\mathbf{v}_{m}=\langle 1,0, \ldots, 0\rangle$. For $1 \leq i \leq m-1$, denote the vectors as $\mathbf{v}_{i}=\left\langle\alpha_{i}, \mathbf{y}_{i}\right\rangle$, for some $\alpha_{i} \in \mathbb{R}$ and $\mathbf{y}_{i} \in \mathbb{R}^{N-1}$. Now, for any $i \neq 1,\left\langle\mathbf{v}_{1}, \mathbf{v}_{i}\right\rangle=1 \cdot \alpha_{i}+\sum_{i=2}^{m} 0=\alpha_{i}$. However, we know from (4.8) that $\left\langle\mathbf{v}_{1}, \mathbf{v}_{i}\right\rangle \leq 0$, which in turn implies that


\begin{equation*}
\alpha_{i} \leq 0 . \tag{4.9}
\end{equation*}

Now we define $\phi:[q] \rightarrow \mathbb{R}^{q}$ to be $\phi(i)=\mathbf{e}_{i}-\overline{\mathbf{e}}$. For every pair $i, j \in[q]$ we have

$$
\langle\phi(i), \phi(j)\rangle=\left\langle\mathbf{e}_{i}-\overline{\mathbf{e}}, \mathbf{e}_{j}-\overline{\mathbf{e}}\right\rangle=\left\langle\mathbf{e}_{i}, \mathbf{e}_{j}\right\rangle-\left\langle\mathbf{e}_{i}, \overline{\mathbf{e}}\right\rangle-\left\langle\overline{\mathbf{e}}, \mathbf{e}_{j}\right\rangle+\langle\overline{\mathbf{e}}, \overline{\mathbf{e}}\rangle=\left\langle\mathbf{e}_{i}, \mathbf{e}_{j}\right\rangle-1 / q .
$$

Thus, for every $i \in[q]$, we get:


\begin{equation*}
\|\phi(i)\|^{2}=\left\langle\mathbf{e}_{i}, \mathbf{e}_{i}\right\rangle-1 / q=\frac{(q-1)}{q} . \tag{4.10}
\end{equation*}


Also for every $i \neq j \in[q]$, we have:


\begin{equation*}
\langle\phi(i), \phi(j)\rangle=-\frac{1}{q} . \tag{4.11}
\end{equation*}

Exercise 4.5. In Section 4.2.2, we saw that random linear code meets the GV bound. It is natural to ask the question for general random codes. (By a random $(n, k)_{q}$ code, we mean the following: for each of the $q^{k}$ messages, pick a random vector from $[q]^{n}$. Further, the choices for each codeword is independent.) We will do so in this problem.

\begin{itemize}
  \item[1.] Prove that a random $q$-ary code with rate $R>0$ with high probability has relative distance $\delta \geq H_{q}^{-1}(1-2 R-\varepsilon)$. Note that this is worse than the bound for random linear codes in Theorem 4.2.1.
  \item[2.] Prove that with high probability the relative distance of a random $q$-ary code of rate $R$ is at most $H_{q}^{-1}(1-2 R)+\varepsilon$. In other words, general random codes are worse than random linear codes in terms of their distance.\\
Hint: Use Chebyshev's inequality (Lemma 3.1.8).
\end{itemize}

Exercise 4.9. In this problem we will derive the GV bound using a graph-theoretic proof, which is actually equivalent to the greedy proof we saw in Section 4.2.1. Let $1 \leq d \leq n$ and $q \geq 1$ be integers. Now consider the graph $G_{n, d, q}=(V, E)$, where the vertex set is the set of all vectors in $[q]^{n}$. Given two vertices $\mathbf{u} \neq \mathbf{v} \in[q]^{n}$, we have the edge ( $u, v$ ) $\in E$ if and only if $\Delta(\mathbf{u}, \mathbf{v})<d$. An independent set of a graph $G=(V, E)$ is a subset $I \subseteq V$ such that for every $u \neq v \in I$, we have that $(u, v)$ is not an edge. We now consider the following sub-problems:

\begin{itemize}
  \item[]
  \begin{itemize}
    \item[1.] Argue that any independent set $C$ of $G_{n, d, q}$ is a $q$-ary code of distance $d$.
    \item[2.] The degree of a vertex in a graph $G$ is the number of edges incident on that vertex. Let $\Delta$ be the maximum degree of any vertex in $G=(V, E)$. Then argue that $G$ has an independent set of size at least $\frac{|V|}{\Delta+1}$.
    \item[3.] Using parts 1 and 2 argue the GV bound.
  \end{itemize}
\end{itemize}

Exercise 4.13. Our goal in this problem is to improve the bound in part 1 in Theorem 4.4.1. Towards that end,

\begin{itemize}
  \item[1.] Prove that the following holds for every $k \geq 1$. There exists $k+1$ vectors $\mathbf{v}_{i}^{k} \in \mathbb{R}^{k}$ for $i \in[k+1]$ such that (1) $\left\|\mathbf{v}_{i}^{k}\right\|_{2}^{2}=1$ for every $i \in[k+1]$ and (2) $\left\langle\mathbf{v}_{i}^{k}, \mathbf{v}_{j}^{k}\right\rangle=-\frac{1}{k}$ for every $i \neq j \in[k+1]$.
  \item[2.] Using the above part, or otherwise, prove the following result. Let $C$ be a $q$ code of block length $n$ and distance $\left(1-\frac{1}{q}\right) n$. Then $|C| \leq 2(q-1) n$. (Note that this is a factor $q /(q-1)$ better than part 1 in Theorem 4.4.1.)
\end{itemize}
